INSERT INTO changelog (title, body, created_at) VALUES ('«Підтверди» з телефона і прохання → правки', 'Нові пропозиції «Підтверди» тепер приходять тобі в Telegram з кнопками ✓ Так / ✕ Ні — розбираєш, не заходячи в систему (тумблер у Можливостях: «…і кнопками ✓/✕ мені в Telegram»; стара черга не надсилається, тільки нове). Якщо ✓ на «нове прохання» клієнта, в якого один наш продукт (напр. Аква Віта → Oselya CRM), — крім задачі зʼявляється правка R-N у цьому проєкті. Продажі: «швидкість першого контакту» рахується тільки по живих лідах (до 7 днів), без архіву з імпорту — раніше показувало «13 днів». Діагностика реклами коротша: одна фраза про дірку і 3 дії, «як зробити» — у попапі; старий довгий висновок сховано, натисни «Розібрати знову».', datetime('now'));
